<?php
$config=require __DIR__."/config.php";require __DIR__."/lib/events.php";
$events=load_events($config);$event=preg_replace("/[^a-zA-Z0-9_-]/","",$_GET["event"]??"");$meta=$events[$event]??null;
if(!$meta){http_response_code(404);exit("Galeri tidak ditemukan");}
if(($meta["visibility"]??"private")!=="public"){http_response_code(403);$private=true;}else{$private=false;}
$photos=[];$dir=$config["storage"]."/".$event;if(!$private&&is_dir($dir)){foreach(glob($dir."/*.{jpg,jpeg,png,JPG,JPEG,PNG}",GLOB_BRACE)?:[] as $p)$photos[]=basename($p);rsort($photos);}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($meta["name"])?> — FOTOGRAFER</title><link rel="stylesheet" href="assets/app.css"></head><body><header class="sitebar"><div class="brand">FOTOGRAFER<small>INSTANT PHOTO DELIVERY</small></div><?php if(!$private):?><span class="count"><?=count($photos)?> FOTO</span><?php endif?></header><main class="wrap"><?php if($private):?><div class="empty"><span class="badge private">PRIVATE</span><h1>Galeri privat</h1><p>Galeri ini tidak tersedia untuk akses publik.</p></div><?php else:?><div class="topline"><div><div class="eyebrow">Galeri acara</div><h1><?=htmlspecialchars($meta["name"])?></h1><p>Foto terbaru muncul otomatis saat fotografer mengirimkannya.</p></div><span class="badge">PUBLIC</span></div><?php if($photos):?><div class="gallery"><?php foreach($photos as $f):?><a class="photo" href="photo.php?event=<?=urlencode($event)?>&file=<?=urlencode($f)?>"><img loading="lazy" src="photo.php?event=<?=urlencode($event)?>&file=<?=urlencode($f)?>" alt=""></a><?php endforeach?></div><?php else:?><div class="empty">Belum ada foto di galeri ini.</div><?php endif?><?php endif?></main><?php if(!$private):?><script>setTimeout(()=>location.reload(),5000)</script><?php endif?></body></html>